# La même fonction de dérivation de clé traduite en Python
def derive_ks(key, salt, index):
    x = (key ^ salt) ^ index
    x &= 0xFFFFFFFF
    if x == 0: x = 2654435769
    x ^= (x << 13) & 0xFFFFFFFF
    x &= 0xFFFFFFFF
    x ^= (x >> 17)
    x ^= (x << 5) & 0xFFFFFFFF
    x &= 0xFFFFFFFF
    return x & 0xFF

